category, b.final_ros AS online_final_ros, b.natural_ros AS online_natural_ros, b.sku_class FROM ( SELECT o.sku_group, CASE WHEN r.size IS NOT NULL THEN o.sku_group || \'-\' || r.size ELSE o.\"ITEM CODE\" END AS \"ITEM CODE\", o.branch_code_priority, o.\"BRANCH NAME\", o.git_date, o.git_source, CASE WHEN r.size IS NOT NULL AND o.git_source = \'B2B\' THEN DIV0(o.qty, o.pp_depth) * r.units_per_pack ELSE o.qty * COALESCE(r.units_per_pack, 1) END AS qty, o.status, o.aging FROM ( SELECT ov.*, CASE WHEN ov.sku_group ILIKE \'%MSQ%\' THEN NULL WHEN ov.\"ITEM CODE\" ILIKE \'PP-%\' THEN TRY_TO_NUMBER(SPLIT_PART(ov.\"ITEM CODE\", \'-\', 4)) WHEN REGEXP_LIKE(SPLIT_PART(ov.\"ITEM CODE\", \'-\', 1), \'^PP[0-9]+$\', \'i\') THEN TRY_TO_NUMBER(REGEXP_SUBSTR(SPLIT_PART(ov.\"ITEM CODE\", \'-\', 1), \'[0-9]+\')) END AS pp_depth FROM overall ov ) o LEFT JOIN deatilas d ON o.sku_group = d.sku_group LEFT JOIN meta m ON UPPER(o.sku_group) = m.sku_group LEFT JOIN prepack_ratio r ON o.pp_depth = r.depth AND r.garment_type = CASE WHEN UPPER(COALESCE(d.category, m.category)) IN (\'BELTS\', \'BOXERS\', \'CARGO PANTS\',\'CHINOS\', \'JEANS\',\'JOGGERS & TRACKPANTS\', \'SHORTS\', \'TROUSERS\') THEN \'BOTTOM\' ELSE \'TOP\' END ) a LEFT JOIN deatilas b ON a.SKU_GROUP = b.sku_group LEFT JOIN meta m2 ON UPPER(a.SKU_GROUP) = m2.sku_group ) where sku_group not like \'%CB%\' ) ), haa as ( Select * from ( SELECT DISTINCT branch_code, marketplace_mapped, ROW_NUMBER() OVER (PARTITION BY branch_code ORDER BY order_date DESC) AS rn FROM snitch_db.maplemonk.STORE_fact_items_offline) WHERE rn = 1 ) Select a.SKU_GROUP, a.\"ITEM CODE\", a.GIT_DATE, a.GIT_SOURCE, a.QTY, a.STATUS, a.AGING, a.PRODUCT_NAME, a.CATEGORY, a.ONLINE_FINAL_ROS, a.ONLINE_NATURAL_ROS, a.SKU_CLASS, CASE WHEN a.\"BRANCH NAME\" = \'SNITCH - COFO - INFINITY ANDHERI -MUMBAI\' THEN 28 WHEN a.\"BRANCH NAME\" = \'SNITCH - FOCO - C ROAD -JODHPUR\' THEN 40 WHEN a.\"BRANCH NAME\" = \'SNITCH - COFO - METRO MALL -KALYAN\' THEN 42 WHEN a.\"BRANCH NAME\" =