E\", \'DD-MM-YYYY\') ELSE NULL END AS git_date, \'PUV\' AS git_source, SUM(\"PUR QTY\") AS qty, \'PUV Verification Pending\' as Status, DATEDIFF( DAY, git_date, CURRENT_DATE ) AS aging from ( SELECT a.*, b.store_code AS branch_code_priority FROM snitch_db.maplemonk.final_puv_verification a LEFT JOIN ( SELECT store_name::TEXT AS store_name, store_code FROM snitch_db.maplemonk.OFFLINE_STORE_DETAILED_MAPPING ) b ON a.\"BRANCH NAME\"::TEXT = b.store_name WHERE LOWER(\"GOODS IN TRANSIT\") = \'true\' ) GROUP BY 1,2,3,4,5 Union ALL Select UPPER(CASE WHEN UPPER(TRIM(\"SKU\")) LIKE \'PP%\' THEN SPLIT_PART(\"SKU\", \'-\', 2) || \'-\' || SPLIT_PART(\"SKU\", \'-\', 3) WHEN UPPER(TRIM(\"SKU\")) LIKE \'4MTL00%\' THEN TRIM(\"SKU\") WHEN UPPER(\"SKU\") LIKE \'4C-%\' OR UPPER(\"SKU\") LIKE \'MP-%\' OR UPPER(\"SKU\") LIKE \'FK-%\' THEN SPLIT_PART(\"SKU\", \'-\', 1) || \'-\' || SPLIT_PART(\"SKU\", \'-\', 2) || \'-\' || SPLIT_PART(\"SKU\", \'-\', 3) WHEN UPPER(\"SKU\") LIKE \'SH%\' THEN LEFT(\"SKU\", LENGTH(UPPER(\"SKU\")) - POSITION(\'-\' IN REVERSE(UPPER(\"SKU\")))) WHEN POSITION(\'-\' IN \"SKU\") > 0 THEN SPLIT_PART(\"SKU\", \'-\', 1) || \'-\' || SPLIT_PART(\"SKU\", \'-\', 2) ELSE \"SKU\" END) AS sku_group ,* from ( with git as (select final_store::TEXT as FINAL_STORE, order_date, sku, final_status , sum(qty) as q1 from snitch_db.maplemonk.b2b_journey where final_status not in (\'INWARDED\') AND ORDER_NAME NOT LIKE \'%QC%\' group by 1,2,3,4 ), branch as (select store_name::TEXT as STORE_NAME , store_code from snitch_db.maplemonk.OFFLINE_STORE_DETAILED_MAPPING) select g.sku, b.store_code as branch_code, g.final_store as store, g.order_date, \'B2B\' as git_source, g.q1 as qty, g.final_status as status, current_date - g.order_date as aging from git g left join branch b on g.final_store::TEXT = b.store_name ) ) , deatilas as ( select * from ( select UPPER(CASE WHEN UPPER(TRIM(sku_group)) LIKE \'PP%\' THEN SPLIT_PART(sku_group, \'-\', 2) || \'-\' || SPLIT_PART(sku_group, \'-\', 3) WHEN U